import {test,expect} from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';
import {spawn,execFile} from 'node:child_process';
import {promisify} from 'node:util';
import {mkdtempSync,writeFileSync,rmSync,unlinkSync} from 'node:fs';
import {randomBytes,randomUUID} from 'node:crypto';
import {join,resolve} from 'node:path';
import {tmpdir} from 'node:os';

const origin='http://127.0.0.1:5193',password='ResearchOnly!2026Flight',run=promisify(execFile);
test.use({baseURL:origin,storageState:{cookies:[],origins:[]}});
test.skip(!process.env.AEROSCIENCE_ORG_TEST_DATABASE,'Actual isolated PostgreSQL is required; no mock organization service.');
let directory,database,secret,secretFile,child,csrf;let ownedConnections=[];let ownedResearchFlight=null,ownedResearchSelection=false;
async function databaseCommand(action){await run(process.env.DOTNET||'dotnet',[resolve('artifacts/browser-test-host/AeroScience.TestHost.dll'),'--organization-database',action,database],{timeout:20000});}
async function boot(){let diagnostics='';child=spawn(process.env.DOTNET||'dotnet',[resolve('artifacts/organization-test-host/AeroScience.Organization.dll')],{env:{...process.env,ASPNETCORE_ENVIRONMENT:'Development',Organization__LocalDevelopment:'true',Organization__PublicOrigin:origin,Organization__ConnectionString:process.env.AEROSCIENCE_ORG_TEST_DATABASE+';Database='+database,Organization__BootstrapSecretFile:secretFile,Logging__LogLevel__Default:'Warning'},stdio:['ignore','pipe','pipe']});const capture=d=>diagnostics=(diagnostics+d.toString()).slice(-8000);child.stdout.on('data',capture);child.stderr.on('data',capture);child.on('error',e=>capture(e.message));try{await expect.poll(async()=>{try{return(await fetch(origin+'/api/health')).ok;}catch{return false;}},{timeout:20000}).toBeTruthy();}catch(e){throw Error('Organization server startup: '+diagnostics,{cause:e});}}
async function stop(){if(child&&child.exitCode===null&&child.signalCode===null){const exited=new Promise(r=>child.once('exit',r));child.kill('SIGKILL');await exited;}}
async function session(page){const r=await page.request.get('/api/session');expect(r.ok(),await r.text()).toBe(true);const value=await r.json();csrf=value.csrf;return value;}
async function api(page,path,data,method='POST'){const r=await page.request.fetch('/api'+path,{method,headers:{Origin:origin,'X-AeroScience-Organization-CSRF':csrf},...(data?{data}:{})});expect(r.ok(),await r.text()).toBe(true);return r.json();}
async function administrator(page){await session(page);await api(page,'/bootstrap',{secret,organizationName:'Flight Research Lab',description:'Private simulator research',userName:'administrator',password});await api(page,'/sign-in',{userName:'administrator',password});await session(page);}
async function program(page){return api(page,'/organization/programs',{version:1,requestId:randomUUID(),expectedRevision:0,name:'Atmospheric Research Program',description:'Retained server-owned program'});}
const campaignInput=()=>({version:1,requestId:randomUUID(),expectedRevision:0,name:'Autumn Profile Campaign',description:'An altitude investigation',objective:'How does temperature change with altitude?',focus:'scientificResearch',template:{id:'vertical-atmospheric-profile',version:1}});
test.beforeEach(async()=>{ownedConnections=[];ownedResearchFlight=null;ownedResearchSelection=false;directory=mkdtempSync(join(tmpdir(),'aeroscience-org-browser-'));database='aeroscience_p13_'+randomUUID().replaceAll('-','');secret=randomBytes(32).toString('hex');secretFile=join(directory,'bootstrap-secret');writeFileSync(secretFile,secret,{mode:0o600});await databaseCommand('create');await boot();});
test.afterEach(async({playwright})=>{if(ownedConnections.length&&child&&(child.exitCode!==null||child.signalCode!==null))await boot();await clearOwnedConnections(playwright);await stop();if(database)await databaseCommand('drop');if(directory)rmSync(directory,{recursive:true,force:true});});

