test('concurrent campaign edits keep the unsaved draft and preserve the published revision and safe literal text',async({page})=>{
 await administrator(page);const p=await program(page),input=campaignInput(),draft=await api(page,`/organization/programs/${p.id}/campaigns`,input),published=await api(page,`/organization/campaigns/${draft.id}/publish`,{version:1,requestId:randomUUID(),expectedRevision:1});await page.goto('/');await page.getByRole('button',{name:'Open Program',exact:true}).click();const card=page.getByRole('article',{name:draft.name,exact:true});await card.getByRole('button',{name:'Edit Campaign',exact:true}).click();const dialog=page.getByRole('dialog');await dialog.getByLabel('Research question or test objective',{exact:true}).fill('My unsaved question');
 await api(page,`/organization/programs/${p.id}/campaigns/${draft.id}`,{...input,requestId:randomUUID(),expectedRevision:2,objective:'Another administrator saved this question'},'PUT');await dialog.getByRole('button',{name:'Save Draft',exact:true}).click();await expect(dialog.getByRole('alert')).toContainText('newer saved revision');await expect(dialog.getByLabel('Research question or test objective',{exact:true})).toHaveValue('My unsaved question');await page.keyboard.press('Escape');await page.reload();await page.getByRole('button',{name:'Open Program',exact:true}).click();await card.getByRole('button',{name:'Edit Campaign',exact:true}).click();const literal='<img src=x onerror="window.organizationXss=1">';await dialog.getByLabel('Campaign description',{exact:true}).fill(literal);await dialog.getByRole('button',{name:'Save Draft',exact:true}).click();await expect(card).toContainText(literal);expect(await page.evaluate(()=>window.organizationXss)).toBeUndefined();await session(page);const old=await api(page,`/organization/definitions/${draft.id}/revisions/2`,null,'GET');expect(JSON.parse(old.snapshotJson)).toEqual(published);await expect(card).toContainText('Retained published revision 2');
});

