 await administrator(page);await page.setViewportSize({width:375,height:812});await page.goto('/');await expect(page.getByRole('heading',{name:'Organization Overview',exact:true})).toBeVisible();expect((await new AxeBuilder({page}).analyze()).violations).toEqual([]);const create=page.getByRole('button',{name:'Create Program',exact:true});await create.click();await expect(page.getByRole('dialog')).toBeVisible();expect((await new AxeBuilder({page}).include('#editor').analyze()).violations).toEqual([]);await page.keyboard.press('Escape');await expect(create).toBeFocused();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 const rejected=await page.request.post('/api/organization/programs',{headers:{Origin:origin},data:{version:1,requestId:randomUUID(),expectedRevision:0,name:'Not approved',description:''}});expect(rejected.status()).toBe(403);
 const desktop=await playwright.request.newContext();try{const paired=await desktop.post('http://127.0.0.1:5080/api/session',{headers:{Origin:'http://127.0.0.1:5080'},data:{}});expect(paired.ok()).toBe(true);expect((await desktop.get(origin+'/api/organization/overview')).status()).toBe(401);const starters=await desktop.get('http://127.0.0.1:5080/api/research/starters');expect((await starters.json())).toHaveLength(6);}finally{await desktop.dispose();}
