 await page.goto(link);await expect(page.getByRole('heading',{name:'Join Organization',exact:true})).toBeVisible();expect(new URL(page.url()).hash).toBe('');
 await page.getByLabel('New account name',{exact:true}).fill(name);await page.getByLabel('New password',{exact:true}).fill(password);await page.getByLabel('What would you like to research?',{exact:true}).fill('Compare local atmospheric profiles');await page.getByRole('checkbox').check();await page.getByRole('button',{name:'Join Organization',exact:true}).click();await expect(page.getByRole('heading',{name:'Enrollment Saved',exact:true})).toBeVisible();await page.getByRole('button',{name:'Sign In',exact:true}).click();await signIn(page,name);
