 dialog=await existing();await dialog.getByRole('checkbox',{name:'Accept: Enable Ambient pressure',exact:true}).check();const updated=await saveMissionDialog(desktop,'Save Changes');expect(updated.plan.id).toBe(original.id);expect(updated.plan.instruments.find(i=>i.instrumentId==='ambient-temperature').enabled).toBe(false);expect(updated.plan.instruments.find(i=>i.instrumentId==='ambient-pressure').enabled).toBe(true);expect(updated.plan.waypoints).toEqual(original.waypoints);expect(updated.plan.intendedAircraft).toBe(original.intendedAircraft);await expect(dialog).toContainText('Recommendation rejected');await dialog.getByRole('button',{name:'Done',exact:true}).click();
