async function submissionSource(p,e,notes=false){
 const {desktop,row}=p;await row.getByRole('button',{name:'Prepare Mission',exact:true}).click();const dialog=desktop.getByRole('dialog',{name:'Prepare Mission',exact:true});await dialog.getByRole('button',{name:'Create Suggested Mission',exact:true}).click();const saved=await saveMissionDialog(desktop,'Save as New Plan');ownedResearchSelection=true;await dialog.getByRole('button',{name:'Select Mission for Flight',exact:true}).click();await expect(desktop.getByLabel('Choose Mission',{exact:true})).toHaveValue(saved.plan.id);await expect(desktop.locator('#mission-name')).toHaveValue(saved.plan.name);const starting=desktop.waitForResponse(r=>new URL(r.url()).pathname==='/api/missions'&&r.request().method()==='POST');await desktop.getByRole('button',{name:'Start mission',exact:true}).click();const startReply=await starting;expect(startReply.ok(),await startReply.text()).toBe(true);await expect(desktop.getByRole('button',{name:'End mission',exact:true})).toBeVisible();const flight=(await e.get('/api/state')).activeMission;ownedResearchFlight=flight.id;
 const card=desktop.locator('#control').getByRole('article',{name:saved.card.name,exact:true});await card.getByRole('button',{name:'Activate Card',exact:true}).click();if(notes)for(let i=0;i<3;i++)await e.post(`/api/missions/${flight.id}/markers`,{category:'observation',notes:'Original browser pilot observation '+i,requestId:randomUUID()});else{await card.getByRole('button',{name:'Begin Attempt',exact:true}).click();await expect.poll(async()=>(await e.get(`/api/missions/${flight.id}`)).mission.sampleCount).toBeGreaterThanOrEqual(9);await card.getByRole('button',{name:'End Attempt',exact:true}).click();}
 const ending=desktop.waitForResponse(r=>new URL(r.url()).pathname===`/api/missions/${flight.id}/end`&&r.request().method()==='POST');await desktop.getByRole('button',{name:'End mission',exact:true}).click();const ended=await ending;expect(ended.ok(),await ended.text()).toBe(true);const detail=await e.get(`/api/missions/${flight.id}`);const result=await e.post('/api/research/attempts',{requestId:randomUUID(),flightId:flight.id,startUtc:detail.mission.startedUtc,endUtc:detail.mission.endedUtc,cardId:saved.card.id});return{saved,flight:detail.mission,result};
}

